        if PERMITIDOS.match(e):
            return e
        vistos[e.split("@")[1]] = vistos.get(e.split("@")[1], 0) + 1
        return "[email-removido]"

    def walk(o):
        if isinstance(o, str):
            return EMAIL.sub(troca, o)
